def page(slide, filename):
    return f'''<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><style>{CSS}</style></head><body>{slide}</body></html>'''

def top(series, num, light=False):
    return f'<div class="top"><img class="logo" src="{logo_light if light else logo_dark}"><span class="series">{series}</span><span class="number">{num}</span></div>'
def foot(label='CARTMAKERS'):
    return f'<div class="footer"><span>{label}</span><span class="url">cart-makers.com</span></div>'

def dark(series,num,main,extra='',label='CARTMAKERS'):
    return f'<section class="slide">{top(series,num)}<div class="shape"></div><div class="main">{main}{extra}</div>{foot(label)}</section>'
def light(series,num,main,extra='',label='CARTMAKERS'):
    return f'<section class="slide light">{top(series,num,True)}<div class="main">{main}{extra}</div>{foot(label)}</section>'

